func hasError(findings []Finding) bool {
	for _, f := range findings {
		if f.Severity == SeverityHigh {
			return true
		}
	}
	return false
}

// renderFailure is a chart or an overlay that could not be rendered: nothing
// in it was validated, and `helm install` or `kubectl apply -k` would fail the
// same way.
func renderFailure(source, dialect, file, title string, from ToolSource, err error) Finding {
	detail := err.Error()
	var exitErr *exitError
	if errors.As(err, &exitErr) && exitErr.Stderr != "" {
		detail = strings.TrimSpace(exitErr.Stderr)
	}
	first, _, _ := strings.Cut(detail, "\n")
	return Finding{
		ID:          K8sRenderID,
		Title:       title + ": " + first,
		Description: "The directory could not be rendered, so none of its resources were validated.",
		Message:     detail,
		Resolution:  renderResolution(source, from, detail),
		Severity:    SeverityHigh,
		Source:      source,
		File:        file,
		IaCType:     dialect,
	}
}

// How to fix a chart or an overlay that does not render, in the renderer's own
// terms.
const (
	helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
		"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
	kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
	// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
	// refuses a file outside the kustomization's directory, with this message.
	// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
	// `build` (afterSubcommand), where kustomize accepts it.
	loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
		"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
		"or, if your deployment tool allows it, set " +
		"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
)

// mountResolution is added for a kustomize image that could not find a path:
// the container sees only what DevDesk mounts (renderScope), and DevDesk does
// not walk the repository to tell a hidden reference from a broken one.
// ToolConfig's `source` key takes auto, binary or image.
const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
	"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
	"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."

// renderResolution picks the advice for a render failure from the renderer,
// where it ran and what it printed.
func renderResolution(source string, from ToolSource, detail string) string {
	if source != SourceKustomize {
		return helmRenderResolution
	}
	advice := kustomizeRenderResolution
	if strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below") {
		advice = loadRestrictorResolution
	}
----
	f, ok := m.findingsTable.Selected()
	if !ok {
		return shortcut.Unavailable(reasonNoFinding)
	}
	if m.result == nil || m.result.TargetType != scan.TargetDirectory {
		return shortcut.Unavailable(reasonFileNotOnDisk)
	}
	rule, ok := remediation.FixFor(f)
	if !ok {
		return shortcut.Unavailable(noFixReason(f))
	}
	// A refusal the finding alone settles (DEVDESK-688): greyed in advance, with
	// the reason the press of the key would give.
	if rule.Declines != nil {
		if reason := rule.Declines(f); reason != "" {
			return shortcut.Unavailable(reason)
		}
	}
	// Reading the file here would be I/O on a path the header calls every
	// frame, so the declines that need the content are left to the Cmd and
	// reach the footer. What is settled here is everything the finding alone
	// can answer.
	return shortcut.Availability{}
}

// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
// Security finding, what the manifest is missing (DEVDESK-689); for anything
// else, the generic refusal. The fix is tried first, so a rule that has one never
// reaches the missing text.
func noFixReason(f scan.Finding) string {
	if text, ok := remediation.MissingFor(f); ok {
		return text
	}
	return remediation.ReasonNoFixForRule
}

// ── Preparing ────────────────────────────────────────────────────────────────

// prepareMisconfigFix starts the fix by computing it: nothing is asked of the
// user until the file has been read, rewritten and put to git, so the
// confirmation can state what it is about.
func (m Model) prepareMisconfigFix() (tea.Model, tea.Cmd) {
	if a := m.canFixMisconfig(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	f, _ := m.findingsTable.Selected()
	return m, prepareMisconfigFixCmd(m.targetPath, f)
}

// prepareMisconfigFixCmd reads the file, asks the catalog for the edits and
// applies them. The finding is copied in (Rule 110).
//
// A rule that declines here is not an error: it is an answer, and it reaches the
// footer as a warning rather than as a failure.
func prepareMisconfigFixCmd(target string, f scan.Finding) tea.Cmd {
	return func() tea.Msg {
		rule, ok := remediation.FixFor(f)
		if !ok {
			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{noFixReason(f)}}
		}
		rel, reason := rule.FileFor(target, f)
		if reason != "" {
			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
		}
		path := filepath.Join(target, filepath.FromSlash(rel))
		original, err := readFile(path)
		if err != nil {
			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
		}
		edits, reason := rule.Fix(original, f)
		if reason != "" {
			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
		}
		updated, err := patch.Rewrite(original, edits)
		if err != nil {
			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
		}
		diff, err := patch.Diff(rel, original, edits)
		if err != nil {
			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
		}
		file := preparedWrite{File: rel, Path: path, Original: original, Updated: updated}
		if file.State, err = git.StateOf(path); err != nil {
			log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
			file.StateErr = true
		}
		body := rule.Title + "\n\n"
		if rule.Warning != "" {
			body += "Warning: " + rule.Warning + "\n\n"
		}
		return MisconfigFixPreparedMsg{
			Target: target, File: file, FindingFile: f.File,
			Rule: f.ID, Instance: instanceOf(f), Body: body + diff,
			Scope: rule.ScopeOf(updated, edits),
		}
	}
}

// errDeclined carries a catalog refusal through the same channel as a failure,
// so the handler has one message to read, and tells the two apart by type rather
// than by inspecting a string.
----
package remediation

import (
	"fmt"

	"github.com/anthnel/devdesk/internal/scan"
)

// missingRule is what a Pod Security rule without a fix asks of the manifest:
// the rule as it is written for the user, the field with the value the profile
// expects, and what is worth knowing besides. Every entry was read in the source
// of the Trivy check (the checks bundle the recorded output was made with,
// testdata/pss/), none from memory of the standard.
//
// The text is read in a footer that keeps one line and cuts it with an ellipsis,
// 80 columns being the narrow case: need is what comes first and must fit after
// the prefix; detail comes last and may be the part that is cut.
type missingRule struct {
	id     string
	need   string
	detail string
}

// missingRules is keyed by RuleKey. It holds the rules of the Pod Security table
// that have no fix of their own; a rule with a fix (KSV-0017, KSV-0001,
// KSV-0008 to KSV-0010) is absent on purpose, so its confirmation diff is what
// the user sees. KSV-0030 and KSV-0104 have a fix since DEVDESK-688 and stay
// here: the text is shown only for a KSV-0104 Unconfined, which the fix never
// touches and greys in advance. Every other refusal of the seccomp fix shows its
